package dev.gbppimentel.sessionhome;
import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;
/** Developer-only CLI entry; never launched by the UI and never starts/stops an app. */
public final class MetadataCheck {
 public static void main(String[] args){try{Intent a=new Intent(Intent.ACTION_VIEW,Uri.parse("content://session-test/game-a")).setComponent(new ComponentName("dev.session.test","dev.session.test.Game")).putExtra("game_id",1);Intent b=new Intent(a).setFlags(0x10460000);if(!SessionReturn.fingerprint(a).equals(SessionReturn.fingerprint(b)))throw new AssertionError("Resume flags changed identity");if(SessionReturn.fingerprint(a).equals(SessionReturn.fingerprint(new Intent(a).putExtra("game_id",2))))throw new AssertionError("Different title in the same host matched");if(SessionReturn.fingerprint(a).equals(SessionReturn.fingerprint(new Intent(a).setData(Uri.parse("content://session-test/game-b")))))throw new AssertionError("Different game URI matched");if(SessionReturn.fingerprint(a).equals(SessionReturn.fingerprint(new Intent(a).setComponent(new ComponentName("dev.other.test","dev.other.test.Game")))))throw new AssertionError("Different app matched");if(SessionReturn.boot().isEmpty())throw new AssertionError("Missing boot identity");if(!SessionReturn.configuredCompanion("dev.gbppimentel.zzz")||SessionReturn.configuredCompanion("dev.gbppimentel.sessionhome"))throw new AssertionError("Cocoon companion membership mismatch");SessionReturn.init();if(SessionReturn.list(-1).isEmpty())throw new AssertionError("Cannot read tasks across displays");if(SessionReturn.list(0).isEmpty())throw new AssertionError("Cannot read the primary display");System.out.println("8 native task identity and read-only Cocoon checks passed");}catch(Throwable e){System.out.println("Metadata check failed: "+e.getClass().getSimpleName()+" "+e.getMessage());}finally{Runtime.getRuntime().halt(0);}}
}
